/* Flies the moby along its path toward the current node, turning and banking toward it, steps the node at each arrival and now and then drops a puff. Returns nonzero once it has run off the end of the path.
   Adapted from Lombyte's project (GPL-3.0) for PAL by OpenRAC's tools/port.py: src/overlays/l09/gameplay/vendor/003033a0.c, FUN_L09_0030a298. */
int advance_shuttle_along_path(struct Moby *moby) {
    PathFlyerVars *vars = (PathFlyerVars *)moby->pvars;
    PathNodes *path;
    f32 d;
    Vec4 target;
    Vec4 step;
    Vec4 puff;
    int done = 0;

    path = (PathNodes *)gaspar_paths[vars->path];
    vars->lag += (0.0f - vars->lag) * 0.005f;
    qcopy(&target, &path->node[vars->node]);
    target.f[2] += vars->speed * (*(f32 *)&gaspar_shuttle_climb_scale);
    FastVecSub(&step, &target, &moby->pos);
    vec_scale_to_length(&step, &step, vars->speed);
    FastVecAdd(&moby->pos, &moby->pos, &step);
    interpolate_rotation_angle(&moby->rot.z, moby->rot.z,
                     FastAddRots(fast_atan2(path->node[vars->node].f[0] - moby->pos.x,
                                         path->node[vars->node].f[1] - moby->pos.y),
                                 vars->yaw_offset),
                     (1.0f - vars->lag) * 0.02f);
    interpolate_rotation_angle(&moby->rot.x, moby->rot.x, 0.0f, 0.02f);
    interpolate_rotation_angle(&moby->rot.y, moby->rot.y, 0.0f, 0.02f);
    if (vars->dir > 0) {
        f32 v;
        if (FastVecDist(&target, &moby->pos) < vars->speed + vars->speed) {
            vars->node++;
            if (vars->node == path->count)
                done = 1;
        }
        d = FastVecDist(&moby->pos, &path->node[path->count - 1]);
        v = 0.0f;
        ApproachWithVelocity(d, g_frame_time_sq * 3.0f, g_frame_time_sq * 3.0f, g_frame_time * 10.0f, &v, &vars->speed);
    } else {
        f32 v;
        if (FastVecDist(&target, &moby->pos) < vars->speed + vars->speed) {
            vars->node--;
            if (vars->node == -1)
                done = 1;
        }
        d = FastVecDist(&moby->pos, &path->node[0]);
        v = 0.0f;
        ApproachWithVelocity(d, g_frame_time_sq * 3.0f, g_frame_time_sq * 3.0f, g_frame_time * 10.0f, &v, &vars->speed);
    }
    if (path->node[vars->node].f[3] == 42.0f)
        vars->yaw_offset = 0.0f;
    vars->spin = FastAddRots(vars->spin, vars->speed);
    axis_rotation_2d48(vars->unk70, 0, vars->spin);
    if (vec_distance_xy(&moby->pos, &path->node[path->count - 1]) > 8.0f &&
        vec_distance_xy(&moby->pos, &path->node[0]) > 8.0f && !random_integer_below(7)) {
        qcopy(&puff, &moby->pos);
        add_random_offset_to_vector_xyz(&puff, 0.5f);
        puff.f[2] = 25.01f;
        spawn_moving_resizing_height_snapped_alpha_fade_particle(&puff, 0, 0x40103080, vars->speed * 3.0f / (g_frame_time * 10.0f), 12600.0f);
    }
    return done;
}
extern char *MobyGetHitMessage(void *, int, int);
extern void Moby_PlaySound(int, int, int);
extern void spawn_proximity_gated_bolts(void *);
extern void spawn_moby_break_fragments(void *, int, int, int, int, int, int);
extern void spawn_moby_from_placement(void *, int);
extern void DeleteMoby(void *);
/* Breakable update: on a hit, play its sound, drop bolts, spawn pieces and delete itself. */
void BreakableL09_Update(char *m) {
    int hit = 0;
    char *r = MobyGetHitMessage(m, 0x10000, 0);
    switch (*(unsigned char *)(m + 0x20)) {
    case 0:
        m[0x20] = 1;
        break;
    case 1:
        if (r != 0 && *(float *)(r + 0x2C) > 0.0f) hit = 1;
        if (hit) m[0x20] = 2;
        break;
    case 2:
        Moby_PlaySound(0, 0, (int)m);
        spawn_proximity_gated_bolts(m);
        spawn_moby_break_fragments(m, 0x73B, 1, 0x73B, 1, 7, 2);
        spawn_moby_from_placement(m, 0x73A);
        DeleteMoby(m);
        break;
    }
}
